import Anthropic from '@anthropic-ai/sdk';
import 'dotenv/config';

const client = new Anthropic();
// The SDK automatically reads ANTHROPIC_API_KEY from the environment

const message = await client.messages.create({
  model: 'claude-haiku-4-5-20251001',
  max_tokens: 200,
  messages: [
    {
      role: 'user',
      content: 'What is the most exciting thing about AI in 2025? One paragraph.'
    }
  ]
});

console.log(message.content[0].text);

## Node.js 中的异步用法

`await` 关键字意味着这个 SDK 调用是异步的——它在等待响应的过程中不会阻塞。当你构建需要发起多个 API 调用、或者在等待响应的同时还要处理用户输入的应用时，这一点就很重要。

上面的脚本之所以能在顶层使用 `await`，是因为现代 Node.js 在 ES 模块中支持顶层 await。如果你身处一个函数内部，就需要把它包裹起来：

```javascript
async function askClaude(question) {
  const message = await client.messages.create({
    model: 'claude-haiku-4-5-20251001',
    max_tokens: 200,
    messages: [{ role: 'user', content: question }]
  });
  return message.content[0].text;
}

const answer = await askClaude('What is recursion?');
console.log(answer);
```
